const config=window.HABITA;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imagePath=s=>/^(assets\/[a-zA-Z0-9_.\/-]+)$/.test(s)?s:'assets/casa.webp';
const grid=document.querySelector('#project-grid');
grid.innerHTML=config.projects.map((p,i)=>`<a class="project-card" href="#proyecto/${encodeURIComponent(p.id)}"><div class="project-photo"><img src="${imagePath(p.image)}" alt="${esc(p.alt)}" loading="lazy" width="1536" height="1024">${p.demo?'<span class="image-label">Concepto ilustrativo</span>':''}</div><div class="project-meta"><div><h3>${esc(p.title)}</h3><p>0${i+1} &nbsp; / &nbsp; ${esc(p.category)}</p></div><span class="project-arrow" aria-hidden="true">↗</span></div><p class="project-summary">${esc(p.summary)}</p></a>`).join('');
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.innerHTML='Menú <span>＋</span>'}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.innerHTML=open?'Cerrar <span>−</span>':'Menú <span>＋</span>'});
nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const home=document.querySelector('#home-view'),view=document.querySelector('#project-view');
function route(){const hash=location.hash;closeMenu();if(hash.startsWith('#proyecto/')){const id=hash.slice(10);const p=config.projects.find(p=>encodeURIComponent(p.id)===id);if(!p){location.replace('#proyectos');return}const next=config.projects[(config.projects.indexOf(p)+1)%config.projects.length];home.hidden=true;view.hidden=false;view.innerHTML=`<div class="project-head"><a href="#proyectos" class="back">← Volver a proyectos</a><p class="eyebrow">${esc(p.category)}${p.demo?' · CONCEPTO ILUSTRATIVO':''}</p><h1 tabindex="-1">${esc(p.title)}</h1><p class="lead">${esc(p.lead)}</p></div><img class="project-wide" src="${imagePath(p.image)}" alt="${esc(p.alt)}" width="1536" height="1024"><section class="project-story section"><dl class="facts"><div><dt>TIPOLOGÍA</dt><dd>${esc(p.category)}</dd></div><div><dt>ALCANCE</dt><dd>${esc(p.scope)}</dd></div><div><dt>MATERIALIDAD</dt><dd>${esc(p.materials)}</dd></div>${p.demo?'<div><dt>SOBRE ESTA IMAGEN</dt><dd>Visualización generada con IA. Ejemplo de presentación; no es una obra de HABITA.</dd></div>':''}</dl><div><p class="eyebrow">LA IDEA</p><h2>${esc(p.lead)}</h2><p>${esc(p.concept)}</p></div></section><section class="decisions section"><p class="eyebrow">DECISIONES DE DISEÑO</p><div class="decisions-grid">${p.decisions.map((d,i)=>`<article><span>0${i+1}</span><h3>${esc(d[0])}</h3><p>${esc(d[1])}</p></article>`).join('')}</div></section><a class="next-project" href="#proyecto/${encodeURIComponent(next.id)}"><div><p class="eyebrow">SIGUIENTE PROYECTO</p><h2>${esc(next.title)}</h2></div><span aria-hidden="true">↗</span></a>`;document.title=p.title+' — HABITA';window.scrollTo({top:0,behavior:'instant'});view.querySelector('h1').focus({preventScroll:true})}else{const was=view.hidden===false;home.hidden=false;view.hidden=true;document.title='HABITA — Arquitectura para vivir mejor';if(was||hash){requestAnimationFrame(()=>{const target=document.getElementById(hash.slice(1)||'inicio');target?.scrollIntoView({behavior:'instant'})})}}}
window.addEventListener('hashchange',route);route();
document.querySelectorAll('details').forEach(el=>el.addEventListener('toggle',()=>el.querySelector('b').textContent=el.open?'−':'＋'));
const dialog=document.querySelector('dialog');document.querySelector('#contact-open').addEventListener('click',()=>dialog.showModal());dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const hasWhatsapp=/^\d{8,15}$/.test(config.whatsapp);
if(hasWhatsapp){document.querySelector('#contact-explanation').textContent='Cuéntanos qué tienes en mente. Al continuar, se abrirá WhatsApp con tu resumen para que lo revises y lo envíes.';document.querySelector('#brief-submit').textContent='Continuar en WhatsApp ↗'}
document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const message=`Hola HABITA, soy ${f.get('nombre')}.\n\nServicio: ${f.get('servicio')}\nUbicación: ${f.get('ubicacion')}\n\nMi idea:\n${f.get('idea')}`;if(hasWhatsapp){window.open('https://wa.me/'+config.whatsapp+'?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');document.querySelector('#form-status').textContent='Revisa tu mensaje en WhatsApp antes de enviarlo.'}else{const url=URL.createObjectURL(new Blob([message],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Mi-proyecto-HABITA.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Resumen descargado. No hemos enviado ni guardado tus datos.'}});
document.querySelector('#year').textContent=new Date().getFullYear();

if (config.mapsUrl && /^https:\/\//.test(config.mapsUrl)) document.querySelector('#maps-link').href = config.mapsUrl;
